// Determine which reminder to send (24h or 1h)
const hoursUntil = parseFloat($json.hours_until_appointment);
const reminderType = hoursUntil > 2 ? '24h' : '1h';

// Format appointment date/time
const appointmentDate = new Date($json.appointment_date);
const dateStr = appointmentDate.toLocaleDateString('es-ES', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});
const timeStr = appointmentDate.toLocaleTimeString('es-ES', { 
  hour: '2-digit', 
  minute: '2-digit' 
});

// Create reminder message based on type
let telegramMessage = '';

if (reminderType === '24h') {
  telegramMessage = `🏥 Kids Growing - Recordatorio de Cita\n\n` +
    `Hola ${$json.parent_name},\n\n` +
    `Te recordamos que mañana tienes una cita programada:\n\n` +
    `👶 Paciente: ${$json.patient_name}\n` +
    `📅 Fecha: ${dateStr}\n` +
    `🕐 Hora: ${timeStr}\n` +
    `📋 Motivo: ${$json.reason_for_visit}\n\n` +
    `📍 Ubicación: Av. Principal #123, Ciudad\n\n` +
    `Para cancelar o reagendar: +1 (555) 123-4567\n\n` +
    `¡Te esperamos!`;
} else {
  telegramMessage = `⏰ Kids Growing - Tu cita es en 1 hora\n\n` +
    `Hola ${$json.parent_name},\n\n` +
    `Tu cita para ${$json.patient_name} es en aproximadamente 1 hora.\n\n` +
    `🕐 Hora: ${timeStr}\n` +
    `📍 Av. Principal #123, Ciudad\n\n` +
    `Recuerda llegar 10 minutos antes.\n\n` +
    `¡Nos vemos pronto!`;
}

return {
  json: {
    appointmentId: $json.appointment_id,
    patientName: $json.patient_name,
    parentName: $json.parent_name,
    parentEmail: $json.parent_email,
    parentPhone: $json.parent_phone,
    appointmentDateTime: $json.appointment_date,
    reminderType: reminderType,
    telegramMessage: telegramMessage,
    emailSubject: reminderType === '24h' ? 
      '🏥 Recordatorio: Tu cita es mañana en Kids Growing' : 
      '⏰ Tu cita es en 1 hora - Kids Growing',
    emailBody: reminderType === '24h' ?
      `<h2>Recordatorio de Cita</h2>
       <p>Hola ${$json.parent_name},</p>
       <p>Te recordamos que <strong>mañana</strong> tienes una cita programada en Kids Growing:</p>
       <ul>
         <li><strong>Paciente:</strong> ${$json.patient_name}</li>
         <li><strong>Fecha:</strong> ${dateStr}</li>
         <li><strong>Hora:</strong> ${timeStr}</li>
         <li><strong>Motivo:</strong> ${$json.reason_for_visit}</li>
       </ul>
       <p><strong>Ubicación:</strong> Av. Principal #123, Ciudad</p>
       <p>Si necesitas cancelar o reagendar, contáctanos al +1 (555) 123-4567</p>
       <p>¡Te esperamos!</p>
       <p>—<br>Equipo Kids Growing</p>` :
      `<h2>Tu cita es en 1 hora</h2>
       <p>Hola ${$json.parent_name},</p>
       <p>Tu cita para <strong>${$json.patient_name}</strong> es en aproximadamente 1 hora.</p>
       <p><strong>Hora:</strong> ${timeStr}<br>
       <strong>Ubicación:</strong> Av. Principal #123, Ciudad</p>
       <p>Recuerda llegar 10 minutos antes.</p>
       <p>¡Nos vemos pronto!</p>
       <p>—<br>Equipo Kids Growing</p>`
  }
};
